/**
 * @method
 * @name setContnId
 * @description 그리드에서 클릭 row의 변수셋팅
 * @param {Object} obj 컴포넌트
 * @returns {void}
 * @hidden N
 */
scwin.setContnId = function(obj) {
    scwin.gExplDisclsAcptNo = dts_explrediscls_list.getCellData(Number(obj), "EXPLDISCLS_ACPT_NO");
    scwin.gExplDisclsOrdNo = dts_explrediscls_list.getCellData(Number(obj), "EXPLDISCLS_ORD_NO");
    scwin.gIsurCd = dts_explrediscls_list.getCellData(Number(obj), "ISUR_CD");
};

/**
 * @method
 * @name openDisclViewerMIS
 * @description open Discl Viewer MIS 처리
 * @param {*} pAcptNo pAcptNo
 * @param {*} pViewerStat pViewerStat
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.openDisclViewerMIS = async function(pAcptNo, pViewerStat) {
    let url = "/dsclproc/ULDSTF10001.gfm?" + "gAcptNo=" + pAcptNo + "&gViewerStat=" + pViewerStat + "&frameID=" + frame.FrameID + "&gAccssAuthTpCd=01" + "&gAskScrenID=" + 'ULDSTF30221.xml';
    let winTitle = "공시뷰어";
    await $c.frame.CreateDialogFrame("viewer" + pAcptNo, url, winTitle, -50, -50, 1000, 800, "window”");
};

/**
 * @method
 * @name reload
 * @description reload 처리
 * @returns {void}
 * @hidden N
 */
scwin.reload = function() {
    fn_Search();
    $c.frame.path("../").fn_Search();
};

/**
 * @method
 * @name dts_explrediscls_info_OnLoadError
 * @description dts_explrediscls_info 로드 오류 처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.dts_explrediscls_info_OnLoadError = async function() {
    await $c.win.alert(dts_explrediscls_info);
};

/**
 * @method
 * @name dts_explrediscls_list_OnLoadError
 * @description dts_explrediscls_list 로드 오류 처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.dts_explrediscls_list_OnLoadError = async function() {
    await $c.win.alert(dts_explrediscls_list);
};

/**
 * @method
 * @name btn_Close_onclick
 * @description 「닫기」 클릭 이벤트
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.btn_Close_onclick = async function() {
    // self.close();
    await $c.win.closePopup();
};

/**
 * @method
 * @name grd_explrediscls_list_OnDblClick
 * @description 클릭된 값 변수에 셋팅
 * @param {Number} row 행 인덱스
 * @param {*} colid colid
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.grd_explrediscls_list_OnDblClick = async function(row, colid) {
    // 클릭된 값 변수에 셋팅
    scwin.setContnId(row);
    if (colid === "REDISCLS_DISCLS_TITLE") {
        await scwin.openDisclViewerMIS(scwin.gExplDisclsAcptNo, 'R');
    } else if (colid === "DISCLS_PUBL_DDTM") {
        let url = "/dsclmgt/ULDSTF30222.gfm";
        let winTitle = "해명공시 재공시 상세";
        // frame.CreateFrame("EXPLDISCLS_ACPT_NO"+gExplDisclsAcptNo, url , winTitle ,100, 10, 560, 290, "window" , 0, 0, true);
        const options = {
            id: "ULDSTF30222",
            title: "해명공시 재공시 상세",
            type: "browserPopup",
            width: "700px",
            height: "500px",
            callbackFn: "scwin.popupCallback"
        };

        $c.win.openPopup("/dsclmgt/ULDSTF30222.gfm", options);
    }
};

/**
 * @method
 * @name btn_New_onclick
 * @description 「신규」 클릭 이벤트
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.btn_New_onclick = async function() {
    let url = "/dsclmgt/ULDSTF30223.gfm";
    let winTitle = "해명공시 신규 등록";
    // frame.CreateFrame("EXPLDISCLS_ACPT_NO"+gExplDisclsAcptNo, url , winTitle ,50, 30, 800, 500+30, "window" , 0, 0, true);
    const options = {
        id: "ULDSTF30223",
        title: "해명공시 신규 등록",
        type: "browserPopup",
        width: "700px",
        height: "500px",
        callbackFn: "scwin.popupCallback"
    };

    $c.win.openPopup("/dsclmgt/ULDSTF30223.gfm", options);
};

/**
 * @method
 * @name gform_onload
 * @description 패널라운드 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.gform_onload = async function() {
    // 패널라운드 처리
    $c.cm.PanelToGroupBox(panel_1);
    scwin.resizeToWin();
    fn_GetParentValue();

    // 가우스헤더 셋팅
    const sbmOptions = {
        id : "sbm_dts_explrediscls_list",
        action : "/gauceSystemierAdaptor.do",
        ref : "",
        target : "dts_explrediscls_list=body.content",
        isProcessMsg : false
    };

    const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
    // TODO Stage2: sbmRtn 응답 처리 로직 작성 (구 submitDoneHandler 자리)

    //  정보 읽어오기
    fn_ReadInfo();
    fn_Search();
    txb_acpt_no.hide();
    txb_isur_cd.hide();
};

/**
 * @method
 * @name popupCallback
 * @description browserPopup 팝업의 callback 함수. 부모창에서 팝업 결과 값을 처리한다.
 * @param {*} arg 팝업에서 전달받은 값
 * @returns {void}
 * @hidden N
 */
scwin.popupCallback = function (arg) {
    // TO-DO : arg 값 확인 후 업무 로직 추가
};
